    notions: ["parité","multiples","identité en k","diviseurs de 15","arbre de choix"],
    enonce: "a و b و n ثلاثة أعداد صحيحة طبيعية بحيث n و b عددان زوجيان و <span dir=\"ltr\" class=\"expr\">a - 1 = 3n</span><br><span class=\"q\">1) </span>بيّن أنّ <span dir=\"ltr\" class=\"expr\">a + 5</span> مضاعف لـ 6<br><span class=\"q\">2) </span>استنتج أنّ العدد <span dir=\"ltr\" class=\"expr\">ab + 5b</span> مضاعف للعدد 12<br><span class=\"q\">3) </span>حدّد مجموعة E للأعداد الصحيحة الطبيعية t التي تجعل <span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">t - 3</span></span></span> عددا صحيحا طبيعيا<br><span class=\"q\">4) </span>حدّد كم مجموعة الأعداد ذات ثلاثة أرقام مختلفة التي يمكن تكوينها من عناصر E الأصغر من 10",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"العدد الزوجي يُكتب 2k حيث k عدد صحيح طبيعي"},{"quoi":"من المعطى","math":"<span dir=\"ltr\" class=\"expr\">a = 3n + 1</span>"},{"quoi":"و n زوجي","math":"<span dir=\"ltr\" class=\"expr\">n = 2k</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">a = 6k + 1</span>"},{"quoi":"نضيف 5","math":"<span dir=\"ltr\" class=\"expr\">a + 5 = 6k + 6</span>"},{"quoi":"نُخرج العامل 6","math":"<span dir=\"ltr\" class=\"expr\">6k + 6 = 6(k + 1)</span>"},{"quoi":"النتيجة","math":"العدد <span dir=\"ltr\" class=\"expr\">a + 5</span> مضاعف للعدد 6"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"القاعدة","math":"جداء مضاعف لـ 2 في مضاعف لـ 6 هو مضاعف لـ 12"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">a × b + 5 × b = b(a + 5)</span>"},{"quoi":"و العدد b زوجي","math":"<span dir=\"ltr\" class=\"expr\">b = 2m</span>"},{"quoi":"و قد رأينا","math":"<span dir=\"ltr\" class=\"expr\">a + 5 = 6(k + 1)</span>"},{"quoi":"نضرب","math":"<span dir=\"ltr\" class=\"expr\">b(a + 5) = 2m × 6(k + 1)</span>"},{"quoi":"نجمع العاملين","math":"<span dir=\"ltr\" class=\"expr\">2 × 6 = 12</span>"},{"quoi":"النتيجة","math":"العدد <span dir=\"ltr\" class=\"expr\">ab + 5b</span> مضاعف للعدد 12"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"القاعدة","math":"الكسر <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">t - 3</span></span></span> عدد صحيح طبيعي إذا كان <span dir=\"ltr\" class=\"expr\">t - 3</span> قاسما موجبا للعدد 15"},{"quoi":"قواسم 15 الموجبة","math":"<span dir=\"ltr\" class=\"expr\">1 × 15 = 15</span>"},{"quoi":"و","math":"<span dir=\"ltr\" class=\"expr\">3 × 5 = 15</span>"},{"quoi":"فالقيم الممكنة لـ <span dir=\"ltr\" class=\"expr\">t - 3</span> هي 1 و 3 و 5 و 15","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">1</span></span> = 15</span>"},{"quoi":"أي","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">4 - 3</span></span> = 15</span>"},{"quoi":"و","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">6 - 3</span></span> = 5</span>"},{"quoi":"و","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">8 - 3</span></span> = 3</span>"},{"quoi":"و","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">18 - 3</span></span> = 1</span>"},{"quoi":"النتيجة","math":"المجموعة E هي 4 و 6 و 8 و 18"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"القاعدة","math":"شجرة الاختيار: عدد الفروع في كلّ مستوى ينقص بواحد لأنّ الأرقام مختلفة"},{"quoi":"عناصر E الأصغر من 10","math":"هي 4 و 6 و 8"},{"quoi":"اختيار رقم المئات","math":"3 إمكانيات"},{"quoi":"ثمّ رقم العشرات من الباقيين","math":"<span dir=\"ltr\" class=\"expr\">3 - 1 = 2</span>"},{"quoi":"ثمّ رقم الآحاد وحيد","math":"<span dir=\"ltr\" class=\"expr\">3 - 2 = 1</span>"},{"quoi":"نضرب فروع الشجرة","math":"<span dir=\"ltr\" class=\"expr\">3 × 2 × 1 = 6</span>"},{"quoi":"النتيجة","math":"عدد هذه الأعداد هو 6"}],
