    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"المستقيم العمودي على مستو يكون عموديا على كلّ مستقيم من ذلك المستوي"},{"quoi":"المعطى","math":"<span dir=\"ltr\" class=\"expr\">AS = 4</span>"},{"quoi":"و ضلع المربّع","math":"<span dir=\"ltr\" class=\"expr\">AB = 4</span>"},{"quoi":"فالمثلّث ABS قائم في A، و فيتاغور يعطي","math":"<span dir=\"ltr\" class=\"expr\">SB<sup>2</sup> = 16 + 16</span>"},{"quoi":"نبسّط الجذر","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">32</span></span> = 4<span class=\"rad\"><span class=\"rcd\">2</span></span></span>"},{"quoi":"النتيجة","math":"المثلّث ABS قائم الزاوية في A، و <span dir=\"ltr\" class=\"expr\">SB = 4<span class=\"rad\"><span class=\"rcd\">2</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"القاعدة","math":"المثلّث الذي أضلاعه الثلاثة متقايسة متقايس الأضلاع"},{"quoi":"من السؤال السابق","math":"<span dir=\"ltr\" class=\"expr\">SB = 4<span class=\"rad\"><span class=\"rcd\">2</span></span></span>"},{"quoi":"و بنفس البرهان مع (AD)","math":"<span dir=\"ltr\" class=\"expr\">SD = 4<span class=\"rad\"><span class=\"rcd\">2</span></span></span>"},{"quoi":"و [BD] قطر المربّع ضلعه 4","math":"<span dir=\"ltr\" class=\"expr\">BD = 4<span class=\"rad\"><span class=\"rcd\">2</span></span></span>"},{"quoi":"فالأضلاع الثلاثة متقايسة","math":"<span dir=\"ltr\" class=\"expr\">SB = BD</span>"},{"quoi":"النتيجة","math":"المثلّث SBD متقايس الأضلاع ضلعه <span dir=\"ltr\" class=\"expr\">4<span class=\"rad\"><span class=\"rcd\">2</span></span></span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"القاعدة","math":"المستقيم العمودي على مستقيمين متقاطعين من مستو يكون عموديا على ذلك المستوي"},{"quoi":"قطرا المربّع متعامدان","math":"المستقيمان (BD) و (AC) متعامدان"},{"quoi":"و (AS) عمودي على مستوي القاعدة","math":"المستقيمان (BD) و (AS) متعامدان"},{"quoi":"و (AC) و (AS) متقاطعان في A و هما من المستوي (ASC)","math":"إذن شرط القاعدة متحقّق"},{"quoi":"نتحقّق عدديا من التماثل","math":"<span dir=\"ltr\" class=\"expr\">SB = SD</span>"},{"quoi":"و","math":"<span dir=\"ltr\" class=\"expr\">OB = OD</span>"},{"quoi":"النتيجة","math":"المستقيم (BD) عمودي على المستوي (ASC)"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"القاعدة","math":"في مثلّث قائم، مربّع ضلع القائمة يساوي جداء الوتر في مسقط ذلك الضلع عليه"},{"quoi":"المثلّث AOS قائم في A حيث","math":"<span dir=\"ltr\" class=\"expr\">AO = 2<span class=\"rad\"><span class=\"rcd\">2</span></span></span>"},{"quoi":"و","math":"<span dir=\"ltr\" class=\"expr\">AS = 4</span>"},{"quoi":"فالوتر","math":"<span dir=\"ltr\" class=\"expr\">OS = 2<span class=\"rad\"><span class=\"rcd\">6</span></span></span>"},{"quoi":"و العلاقة المترية تعطي","math":"<span dir=\"ltr\" class=\"expr\">OK = AO^<span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">OS</span></span></span>"},{"quoi":"أي","math":"<span dir=\"ltr\" class=\"expr\">OK = <span class=\"frac\"><span class=\"num\">2<span class=\"rad\"><span class=\"rcd\">6</span></span></span><span class=\"den\">3</span></span></span>"},{"quoi":"و (BD) عمودي على (ASC) و K منه","math":"المثلّث BOK قائم في O"},{"quoi":"نطبّق فيتاغور","math":"<span dir=\"ltr\" class=\"expr\">BK<sup>2</sup> = 8 + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span></span>"},{"quoi":"أي","math":"<span dir=\"ltr\" class=\"expr\">BK<sup>2</sup> = <span class=\"frac\"><span class=\"num\">32</span><span class=\"den\">3</span></span></span>"},{"quoi":"النتيجة","math":"لنا <span dir=\"ltr\" class=\"expr\">BK = <span class=\"frac\"><span class=\"num\">4<span class=\"rad\"><span class=\"rcd\">6</span></span></span><span class=\"den\">3</span></span></span>"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"القاعدة","math":"المستقيم الموازي لمستو و له نقطة منه يكون محتوى فيه"},{"quoi":"المستقيمان Δ و (AS) عموديان على المستوي (ABC)","math":"إذن Δ يوازي (AS)"},{"quoi":"و (AS) مستقيم من المستوي (ASC)","math":"إذن Δ يوازي المستوي (ASC)"},{"quoi":"و O منتصف [AC] حيث","math":"<span dir=\"ltr\" class=\"expr\">OA = 2<span class=\"rad\"><span class=\"rcd\">2</span></span></span>"},{"quoi":"و","math":"<span dir=\"ltr\" class=\"expr\">OC = 2<span class=\"rad\"><span class=\"rcd\">2</span></span></span>"},{"quoi":"فالنقطة O من المستقيم (AC) إذن من المستوي (ASC)","math":"إذن لـ Δ نقطة منه"},{"quoi":"النتيجة","math":"المستقيم Δ محتوى في المستوي (ASC)"},{"quoi":"","math":"<b>6)</b>"},{"quoi":"القاعدة","math":"الهرم منتظم إذا كانت قاعدته منتظمة و سقط رأسه عموديا على مركزها"},{"quoi":"النقطة M من Δ","math":"إذن (OM) عمودي على مستوي القاعدة"},{"quoi":"و O مركز المربّع ABCD حيث","math":"<span dir=\"ltr\" class=\"expr\">OA = OB</span>"},{"quoi":"و","math":"<span dir=\"ltr\" class=\"expr\">OC = OD</span>"},{"quoi":"فالرأس M يسقط عموديا على مركز القاعدة","math":"<span dir=\"ltr\" class=\"expr\">MA = 2<span class=\"rad\"><span class=\"rcd\">3</span></span></span>"},{"quoi":"و","math":"<span dir=\"ltr\" class=\"expr\">MB = 2<span class=\"rad\"><span class=\"rcd\">3</span></span></span>"},{"quoi":"النتيجة","math":"الهرم MABCD منتظم"},{"quoi":"","math":"<b>7)</b>"},{"quoi":"القاعدة","math":"حجم الهرم يساوي ثلث جداء مساحة القاعدة في الارتفاع"},{"quoi":"ضلع المربّع","math":"<span dir=\"ltr\" class=\"expr\">AB = 4</span>"},{"quoi":"فمساحة القاعدة","math":"<span dir=\"ltr\" class=\"expr\">4 × 4 = 16</span>"},{"quoi":"و الارتفاع","math":"<span dir=\"ltr\" class=\"expr\">OM = 2</span>"},{"quoi":"نضرب ثمّ نقسم على 3","math":"<span dir=\"ltr\" class=\"expr\">16 × <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> = <span class=\"frac\"><span class=\"num\">32</span><span class=\"den\">3</span></span></span>"},{"quoi":"النتيجة","math":"حجم الهرم MABCD يساوي <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">32</span><span class=\"den\">3</span></span></span>"}],
