    notions: ["critère de divisibilité par 3","par 5","par 4","par 2","décomposer un diviseur en facteurs premiers entre eux","énumérer des couples de chiffres"],
    enonce: "<span class=\"q\">1) </span>أوجد الرقمين a و b حتّى يصبح العدد 3a4b يقبل القسمة على 15<br><span class=\"q\">2) </span>أوجد الرقمين a و b حتّى يصبح العدد 36a8b يقبل القسمة على 12<br><span class=\"q\">3) </span>أوجد الرقمين a و b حتّى يصبح العدد 3a5b يقبل القسمة على 6",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"عدد يقبل القسمة على 15 إذا و فقط إذا قبلها على 3 و على 5 ; و القسمة على 5 تُقرأ على رقم الآحاد، و القسمة على 3 على مجموع الأرقام"},{"quoi":"القسمة على 5 تفرض رقم الآحاد","math":"العدد b يساوي 0 أو يساوي 5"},{"quoi":"في حالة <span dir=\"ltr\" class=\"expr\">b = 0</span> يصير مجموع الأرقام","math":"<span dir=\"ltr\" class=\"expr\">3 + a + 4 + 0 = 7 + a</span>"},{"quoi":"و هو مضاعف للثلاثة عندما a من {2 ; 5 ; 8}","math":"مثلا <span dir=\"ltr\" class=\"expr\">7 + 2</span> يساوي 9"},{"quoi":"نتحقّق من الأوّل","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3240</span><span class=\"den\">15</span></span> = 216</span>"},{"quoi":"و من الثالث","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3840</span><span class=\"den\">15</span></span> = 256</span>"},{"quoi":"في حالة <span dir=\"ltr\" class=\"expr\">b = 5</span> يصير المجموع","math":"<span dir=\"ltr\" class=\"expr\">3 + a + 4 + 5 = 12 + a</span>"},{"quoi":"و هو مضاعف للثلاثة عندما a من {0 ; 3 ; 6 ; 9}","math":"مثلا <span dir=\"ltr\" class=\"expr\">12 + 0</span> يساوي 12"},{"quoi":"نتحقّق من الأوّل","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3045</span><span class=\"den\">15</span></span> = 203</span>"},{"quoi":"و من الأخير","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3945</span><span class=\"den\">15</span></span> = 263</span>"},{"quoi":"النتيجة","math":"الأعداد الممكنة هي 3240 و 3540 و 3840 و 3045 و 3345 و 3645 و 3945"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"القاعدة","math":"عدد يقبل القسمة على 12 إذا و فقط إذا قبلها على 4 و على 3 ; و القسمة على 4 تُقرأ على العدد المكوّن من الرقمين الأخيرين"},{"quoi":"الرقمان الأخيران يكوّنان العدد 8b، و مضاعفات الأربعة بينها","math":"هي 80 و 84 و 88"},{"quoi":"نتحقّق من الأوّل","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">80</span><span class=\"den\">4</span></span> = 20</span>"},{"quoi":"و من الأخير","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">88</span><span class=\"den\">4</span></span> = 22</span>"},{"quoi":"مجموع الأرقام","math":"<span dir=\"ltr\" class=\"expr\">3 + 6 + a + 8 + b = 17 + a + b</span>"},{"quoi":"في حالة <span dir=\"ltr\" class=\"expr\">b = 0</span> يصير المجموع <span dir=\"ltr\" class=\"expr\">17 + a</span>، فيكون a من {1 ; 4 ; 7}","math":"مثلا <span dir=\"ltr\" class=\"expr\">17 + 1</span> يساوي 18"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">36180</span><span class=\"den\">12</span></span> = 3015</span>"},{"quoi":"في حالة <span dir=\"ltr\" class=\"expr\">b = 4</span> يصير المجموع <span dir=\"ltr\" class=\"expr\">21 + a</span>، فيكون a من {0 ; 3 ; 6 ; 9}","math":"مثلا <span dir=\"ltr\" class=\"expr\">21 + 0</span> يساوي 21"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">36084</span><span class=\"den\">12</span></span> = 3007</span>"},{"quoi":"في حالة <span dir=\"ltr\" class=\"expr\">b = 8</span> يصير المجموع <span dir=\"ltr\" class=\"expr\">25 + a</span>، فيكون a من {2 ; 5 ; 8}","math":"مثلا <span dir=\"ltr\" class=\"expr\">25 + 2</span> يساوي 27"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">36288</span><span class=\"den\">12</span></span> = 3024</span>"},{"quoi":"النتيجة","math":"هناك عشرة أعداد ممكنة، ثلاثة عند <span dir=\"ltr\" class=\"expr\">b = 0</span> و أربعة عند <span dir=\"ltr\" class=\"expr\">b = 4</span> و ثلاثة عند <span dir=\"ltr\" class=\"expr\">b = 8</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"القاعدة","math":"عدد يقبل القسمة على 6 إذا و فقط إذا كان زوجيا و قبل القسمة على 3"},{"quoi":"القسمة على 2 تفرض رقم الآحاد","math":"العدد b من {0 ; 2 ; 4 ; 6 ; 8}"},{"quoi":"مجموع الأرقام","math":"<span dir=\"ltr\" class=\"expr\">3 + a + 5 + b = 8 + a + b</span>"},{"quoi":"في حالة <span dir=\"ltr\" class=\"expr\">b = 0</span> فـ a من {1 ; 4 ; 7}","math":"نتحقّق: 3150 يساوي <span dir=\"ltr\" class=\"expr\">6 × 525</span>"},{"quoi":"نقسم","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3150</span><span class=\"den\">6</span></span> = 525</span>"},{"quoi":"في حالة <span dir=\"ltr\" class=\"expr\">b = 2</span> فـ a من {2 ; 5 ; 8}","math":"نتحقّق: 3252 يساوي <span dir=\"ltr\" class=\"expr\">6 × 542</span>"},{"quoi":"نقسم","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3252</span><span class=\"den\">6</span></span> = 542</span>"},{"quoi":"في حالة <span dir=\"ltr\" class=\"expr\">b = 4</span> فـ a من {0 ; 3 ; 6 ; 9}","math":"نتحقّق: 3054 يساوي <span dir=\"ltr\" class=\"expr\">6 × 509</span>"},{"quoi":"نقسم","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3054</span><span class=\"den\">6</span></span> = 509</span>"},{"quoi":"في حالة <span dir=\"ltr\" class=\"expr\">b = 6</span> فـ a من {1 ; 4 ; 7}","math":"نتحقّق: 3156 يساوي <span dir=\"ltr\" class=\"expr\">6 × 526</span>"},{"quoi":"نقسم","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3156</span><span class=\"den\">6</span></span> = 526</span>"},{"quoi":"في حالة <span dir=\"ltr\" class=\"expr\">b = 8</span> فـ a من {2 ; 5 ; 8}","math":"نتحقّق: 3258 يساوي <span dir=\"ltr\" class=\"expr\">6 × 543</span>"},{"quoi":"نقسم","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3258</span><span class=\"den\">6</span></span> = 543</span>"},{"quoi":"النتيجة","math":"هناك ستّة عشر عددا ممكنا: ثلاثة لكلّ من <span dir=\"ltr\" class=\"expr\">b = 0</span> و 2 و 6 و 8، و أربعة عند <span dir=\"ltr\" class=\"expr\">b = 4</span>"}],
